    "mail.collectAll": "Collect All",
    "mail.collectOne": "Collect Message",
    "mail.empty": "Your mailbox is empty.",
    "mail.partialNotice": "Bags full — the rest stays in your mailbox.",
    "mail.attachments": "Attachments",
    // Zwei Brief-TEXTE (Jagd-Paket Task 4), final aus dem Persönlichkeits-Paket „Das Reach führt
    // Buch" § E (design/lore/waechter-stimme-pack.md, v1) übernommen — Signaturzeile via \n, s.
    // `.mail-letter-body { white-space: pre-wrap }` in styles/mail.css.
    "mail.letter.brenna.firstChampion": "So the champion's down. I'll admit it just this once: clean work. There's a small something in with this letter, for the road. And don't go saying I never give you anything. The next one is already out there somewhere, and I want its head too.\nBrenna",
    "mail.letter.warden.firstUnique": "You found something out there that doesn't turn up often. I've seen a few pieces like it over the years, and not many. No two of them ever came out the same, so yours is one of a kind. I've put it in the book. Keep it close.\nThe Warden",
    "mail.letter.warden.twoHandedRanged": "A bow takes both hands, and it always did. Some of the older ones in circulation were written up wrong, and that fault was ours, not yours. I have set the record straight. Your shield hand is free now, so whatever you carried there is back in your pack.\nThe Warden",
    "updateNotice.title": "Update {version}",
    "updateNotice.intro": "The game has been updated. You can find the patch notes on the Steam page.",
    "updateNotice.point1": "Hunting is a new skill: set traps, bait them with bait tiers you earn through Fishing, and track every catch in the new hunting log.",
    "updateNotice.point2": "Crafting has been split into two skills: Crafting (leather, bows, strings, shields) and the new Tailoring (weaving, all mage robes, all capes). Your existing progress was divided by what you actually crafted. A word from the developer: I am sorry that this splits your progress — it was the better call for the game, and better made now than later.",
    "updateNotice.point3": "Three equipment kits store full gear sets. One click switches between them — handy when you swap between melee, ranged and magic.",
    "updateNotice.point4": "Combat looks and plays differently now: hand-painted particle effects replace the old sprites, every element has its own effect in battle, and magic weapons carry a Spell Focus. Mana is now called Spell Reserve, it charges your stance instead of paying for spells, and Wisdom now grants status resistance.",
    "updateNotice.point5": "Fibres and cloth are new: gather or farm five fibre tiers, weave them into cloth, and sew mage robes and capes from it.",
    "updateNotice.shield": "Because of the bow change, the shield you had equipped has been moved into your pack. Nothing was lost, and there is a letter in your mailbox explaining it.",
    "updateNotice.close": "Got it",
