    "onboarding.start": "Start playing",
    "onboarding.welcome.title": "Welcome to Grim Reach",
    "onboarding.welcome.body": "A gritty dark-fantasy idle RPG. Train skills, forge gear, and battle your way through a dying world — even while you're away. Here's the core loop in a few steps.",
    "onboarding.gather.title": "1. Gather raw materials",
    "onboarding.gather.body": "Pick a gathering skill (Mining, Woodcutting, Fishing, Foraging…) and start an action. It runs on its own and yields ore, logs, fish and more — the foundation of everything.",
    "onboarding.process.title": "2. Process them",
    "onboarding.process.body": "Use Smithing to smelt bars and forge weapons & armour, or Cooking to turn raw food into healing meals. Processing actions consume inputs from your inventory.",
    "onboarding.equip.title": "3. Equip your gear",
    "onboarding.equip.body": "Open the Character sheet and drag items onto the paperdoll. Your weapon decides your combat style — melee, ranged or magic — and armour boosts defence and health.",
    "onboarding.fight.title": "4. Fight monsters",
    "onboarding.fight.body": "Head to Combat, pick a foe and let the auto-battle run. Choose a combat style (Attack, Power, Defensive) to steer which skill earns XP. Win loot, gold and kill XP.",
    "onboarding.economy.title": "5. Spend & store",
    "onboarding.economy.body": "Sell loot for gold and buy upgrades, food and bigger inventory slots in the Shop. Stash overflow in the Bank so your inventory never clogs up.",
    "onboarding.idle.title": "Progress never stops",
    "onboarding.idle.body": "Your character keeps working while the game is closed — you'll collect offline gains when you return. You can reopen this guide any time from Options. Good luck!",
