    "prestige.count": "Cinderfalls: {n}",
    "prestige.greeting": "Beneath this stone lie the shards of every image the Reach ever broke. The Reach outlived its fall because it kept nothing but what it had learned. Lay down here what you are, and I will record what you were; the ash gets the rest.",
    "prestige.lockedText": "The altar takes only those who have mastered four arts and finished the first volume. Before that it would be no fall, only a stumble.",
    "prestige.confirm.text": "Into the ash go levels, gear, gold and every page of the Chronicle you have opened. With you stay your companions, the knowledge in your hands, the Slayer's Book and everything I have ever recorded about you. Ash is not taken back.",
    "prestige.awakening.text": "You went through the ash, and the ash did not keep you. What it left you, you wear as scars. The Chronicle opens a new page; the pen already knows you.",
