    "mail.attachments": "Anhänge",
    // Final aus § E übernommen (s. EN-Kommentar oben, dieselbe Quelle).
    "mail.letter.brenna.firstChampion": "Der Champion ist also erledigt. Ich gebe es nur dieses eine Mal zu: saubere Arbeit. Ich lege dir eine Kleinigkeit bei, für unterwegs. Und sag nicht, ich hätte dir nie etwas geschenkt. Der Nächste läuft schon irgendwo da draußen herum, und seinen Kopf will ich auch.\nBrenna",
    "mail.letter.warden.firstUnique": "Du hast da draußen etwas gefunden, das nicht oft auftaucht. Ich habe über die Jahre ein paar solcher Stücke gesehen, viele waren es nicht. Keine zwei davon sind je gleich ausgefallen, deins gibt es also nur einmal. Ich habe es ins Buch eingetragen. Behalt es bei dir.\nDer Wächter",
    "mail.letter.warden.twoHandedRanged": "Ein Bogen braucht beide Hände, und das war schon immer so. Bei einigen älteren Stücken stand es falsch im Buch, und der Fehler lag bei uns, nicht bei dir. Ich habe es richtiggestellt. Deine Schildhand ist jetzt frei, was du dort getragen hast, liegt wieder in deinem Gepäck.\nDer Wächter",
    "updateNotice.title": "Update {version}",
    "updateNotice.intro": "Das Spiel wurde aktualisiert. Die Patchnotes findest du auf der Steam-Seite.",
    "updateNotice.point1": "Jagen ist ein neuer Beruf: Stelle Fallen, bestücke sie mit Ködern, deren Stufen du dir im Angeln erarbeitest, und verfolge jeden Fang im neuen Jagdbuch.",
    "updateNotice.point2": "Handwerk wurde in zwei Fertigkeiten geteilt: Handwerk (Leder, Bögen, Sehnen, Schilde) und das neue Schneidern (Weben, alle Magier-Roben, alle Umhänge). Dein bisheriger Fortschritt wurde danach aufgeteilt, was du tatsächlich hergestellt hast. Ein Wort vom Entwickler: Es tut mir leid, dass diese Aufteilung deinen Fortschritt auseinanderzieht — für das Spiel war es die bessere Entscheidung, und ich wollte sie lieber jetzt treffen als später.",
    "updateNotice.point3": "Drei Ausrüstungs-Kits speichern komplette Ausrüstungssätze. Ein Klick wechselt zwischen ihnen — praktisch, wenn du zwischen Nahkampf, Fernkampf und Magie wechselst.",
    "updateNotice.point4": "Kämpfe sehen jetzt anders aus und spielen sich anders: gemalte Partikeleffekte ersetzen die alten Sprites, jedes Element hat im Kampf seine eigene Wirkung, und Magiewaffen tragen einen Zauberfokus. Mana heißt jetzt Zauberreserve, lädt deine Haltung auf statt Zauber zu bezahlen, und Weisheit gibt dir Status-Widerstand.",
    "updateNotice.point5": "Fasern und Stoffe sind neu: Sammle oder baue fünf Faser-Stufen an, webe sie zu Stoff, und näh daraus Magier-Roben und Umhänge.",
    "updateNotice.shield": "Wegen der Bogen-Änderung liegt das Schild, das du getragen hast, jetzt in deinem Gepäck. Verloren ist nichts, und im Postfach findest du einen Brief dazu.",
    "updateNotice.close": "Verstanden",
