    // Ambient-Cockpit (Task #311; Chef-Rückbau 2026-07-24: three.js-Blessing-Wetter entfernt) —
    // app-weiter Vignette/Korn/Nebel/Fackellicht-Layer, s. components/AmbientEffects.tsx + util/ambientPrefs.ts.
    "options.ambient.title": "Ambiente & Effekte",
    "options.ambient.master": "Ambient-Effekte",
    "options.ambient.masterHint": "Eine dezente Vollbild-Ebene aus Vignette und sanftem, warmem Bloom-Schimmer.",
    "options.ambient.reducedMotionHint": "Dein System bevorzugt reduzierte Bewegung, daher ist dies standardmäßig aus. Du kannst es trotzdem einschalten — es bleibt sanft.",
    "options.ambient.vignette": "Vignette",
    "options.ambient.vignetteHint": "Verdunkelt die Bildschirmränder, um den Blick auf die Mitte zu lenken.",
    "onboarding.skip": "Überspringen",
    "onboarding.back": "Zurück",
    "onboarding.next": "Weiter",
    "onboarding.start": "Losspielen",
    "onboarding.welcome.title": "Willkommen bei Grim Reach",
    "onboarding.welcome.body": "Ein grimmiges Dark-Fantasy-Idle-RPG. Trainiere Fertigkeiten, schmiede Ausrüstung und kämpfe dich durch eine sterbende Welt — auch wenn du weg bist. Hier ist der Kern-Loop in wenigen Schritten.",
    "onboarding.gather.title": "1. Rohstoffe sammeln",
    "onboarding.gather.body": "Wähle eine Sammel-Fertigkeit (Bergbau, Holzfällen, Angeln, Sammeln…) und starte eine Aktion. Sie läuft von allein und liefert Erz, Holz, Fisch und mehr — die Basis von allem.",
    "onboarding.process.title": "2. Verarbeiten",
    "onboarding.process.body": "Mit Schmieden schmilzt du Barren und fertigst Waffen & Rüstung, mit Kochen machst du aus rohem Essen heilende Mahlzeiten. Verarbeitungs-Aktionen verbrauchen Materialien aus dem Inventar.",
    "onboarding.equip.title": "3. Ausrüstung anlegen",
    "onboarding.equip.body": "Öffne das Charakterblatt und zieh Gegenstände auf die Puppe. Deine Waffe bestimmt den Kampfstil — Nah-, Fern- oder Magiekampf — und Rüstung erhöht Verteidigung und Leben.",
    "onboarding.fight.title": "4. Monster bekämpfen",
    "onboarding.fight.body": "Geh zum Kampf, wähle einen Gegner und lass die Auto-Schlacht laufen. Wähle einen Kampfstil (Angriff, Wucht, Defensiv), um zu steuern, welcher Skill XP bekommt. Es winken Beute, Gold und Kill-XP.",
    "onboarding.economy.title": "5. Ausgeben & lagern",
    "onboarding.economy.body": "Verkaufe Beute für Gold und kaufe im Shop Upgrades, Nahrung und mehr Inventarplatz. Lagere Überschüsse in der Bank, damit dein Inventar nie verstopft.",
    "onboarding.idle.title": "Der Fortschritt hört nie auf",
    "onboarding.idle.body": "Dein Charakter arbeitet weiter, während das Spiel geschlossen ist — bei deiner Rückkehr kassierst du den Offline-Ertrag. Diese Anleitung kannst du jederzeit in den Optionen erneut öffnen. Viel Erfolg!",
