    "blessing.flavor.bloodmoon": "Der Mond hängt heute Nacht tief und rot über dem Reach. Die Bestien werden dreister — und ihre Beute umso reicher.",
    "blessing.flavor.ashenstorm": "Grauer Ascheregen zieht über Feld und Wald. Was heute gesammelt wird, kommt leichter aus der Erde.",
    "blessing.flavor.silence": "Kein Vogel singt, kein Wind weht, nicht einmal die Esse wagt zu knistern. In dieser Stille arbeitet eine ruhige Hand schneller.",
    "blessing.flavor.rotmist": "Ein fauler Nebel kriecht aus dem Niederland, schwer vom Geruch alten Moders. Bei solchem Wetter kommt manch seltsames Ding zum Vorschein.",
    "blessing.flavor.mistvigil": "Nebel umhüllt die Wachtürme bis zum Morgengrauen, und jeder Wächter bleibt darin wacher. In solchen Nächten bleibt Gelerntes besser haften.",
    "blessing.flavor.greed": "Das Reach selbst scheint heute hungrig nach Münzen zu sein und gibt sie doch bereitwillig her — alte Verstecke geben leichter nach.",
