    // claude:2026-10-18T14:00:00+02:00 - Scherbenaltar / Der Aschesturz (Prestige, Welle D)
    "nav.prestige": "Scherbenaltar",
    "prestige.tab.altar": "Altar",
    "prestige.tab.book": "Narbenbuch",
    "prestige.scars": "Narben",
    "prestige.count": "Aschestürze: {n}",
    "prestige.greeting": "Unter diesem Stein liegen die Scherben aller Bildnisse, die das Reach je zerschlug. Das Reach hat seinen Sturz überstanden, weil es nichts behielt außer dem, was es gelernt hatte. Leg hier nieder, was du bist, und ich trage ein, was du warst; den Rest bekommt die Asche.",
    "prestige.lockedText": "Der Altar nimmt nur, wer vier Künste gemeistert und den ersten Band zu Ende gebracht hat. Vorher wäre es kein Sturz, nur ein Stolpern.",
    "prestige.confirm.text": "In die Asche gehen Stufen, Ausrüstung, Gold und jede Seite der Chronik, die du aufgeschlagen hast. Bei dir bleiben deine Begleiter, das Wissen deiner Hände, der Jägerkodex und alles, was ich je über dich eingetragen habe. Asche wird nicht zurückgenommen.",
    "prestige.awakening.text": "Du bist durch die Asche gegangen, und die Asche hat dich nicht behalten. Was sie dir ließ, trägst du als Narben. Die Chronik schlägt eine neue Seite auf; die Feder kennt dich schon.",
