// `en` ist Pflicht (Referenz-/Fallback-Sprache, s. `useI18n().t`); die übrigen 5 Locales
// (zh/ru/es/pt-BR/fr, 7-Sprachen-Fundament Task #252) sind hier noch OPTIONAL — die UI-Chrome-
// Übersetzung für sie folgt in einer separaten Übersetzungswelle. `t()` fällt bis dahin auf `en`
// zurück. `de` bleibt vollständig (Record<keyof typeof en, string>, s. oben) und compile-enforced.
export const UI_TEXT: { en: Record<string, string> } & Partial<Record<Locale, Record<string, string>>> = {
  en,
  de,
  es,
  "pt-BR": ptBR,
  fr,
  ru,
  zh,
};
